INSERT INTO planning_document_assets (document_id,asset_type,url,mime_type,content_hash_sha256,byte_size,page_count,source_modified_at,retrieved_at,retrieval_status,local_path,ocr_status,extraction_status,extraction_version,error,metadata_json) SELECT id,'plan_sheet','https://www.berlin.de/ba-charlottenburg-wilmersdorf/verwaltung/aemter/stadtentwicklung/vermessung/bebauungsplaene/7b-000b_840x594mm.pdf','application/pdf','1187023f91b9a0065601de81de3aae6733c53dfc57e61124252b6c7febcecee5',8563558,1,'Mon, 16 Aug 2021 17:40:23 +0200','2026-08-01T15:53:50.536Z','downloaded','data/documents/bplans/VII-B--plan_sheet.pdf','pending','pending','pypdf-embedded-text-v1',NULL,'{}' FROM planning_documents WHERE plan_key='VII-B' ON CONFLICT(url) DO UPDATE SET document_id=excluded.document_id,asset_type=excluded.asset_type,mime_type=coalesce(excluded.mime_type,planning_document_assets.mime_type),content_hash_sha256=coalesce(excluded.content_hash_sha256,planning_document_assets.content_hash_sha256),byte_size=coalesce(excluded.byte_size,planning_document_assets.byte_size),page_count=coalesce(excluded.page_count,planning_document_assets.page_count),source_modified_at=coalesce(excluded.source_modified_at,planning_document_assets.source_modified_at),retrieved_at=coalesce(excluded.retrieved_at,planning_document_assets.retrieved_at),retrieval_status=CASE WHEN excluded.retrieval_status='pending' AND planning_document_assets.retrieval_status='downloaded' THEN planning_document_assets.retrieval_status ELSE excluded.retrieval_status END,local_path=coalesce(excluded.local_path,planning_document_assets.local_path),ocr_status=CASE WHEN excluded.ocr_status='pending' AND planning_document_assets.ocr_status IN ('complete','not_needed') THEN planning_document_assets.ocr_status ELSE excluded.ocr_status END,extraction_status=CASE WHEN excluded.extraction_status='pending' AND planning_document_assets.extraction_status IN ('machine_extracted','verified') THEN planning_document_assets.extraction_status ELSE excluded.extraction_status END,extraction_version=coalesce(excluded.extraction_version,planning_document_assets.extraction_version),error=excluded.error,metadata_json=CASE WHEN excluded.metadata_json='{}' THEN planning_document_assets.metadata_json ELSE excluded.metadata_json END,updated_at=CURRENT_TIMESTAMP;
COMMIT;
